The evidence points to a single root cause: ts-order-service's database calls became slow, starting in the abnormal window. Its own network and host look normal, and no span errors or restarts appear anywhere.

```json
{
  "root_causes": [
    {
      "service": "ts-order-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, left(span_name,40) sn, date_trunc('minute', time) m, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms FROM abnormal_traces WHERE service_name='ts-order-service' AND attr_span_kind='Client' GROUP BY ALL ORDER BY sn, m",
          "claim": "ts-order-service SELECT/INSERT/UPDATE ts.orders client spans run about 1.1-1.2 s p50 every minute of the incident."
        },
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) SELECT p, span_name, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms FROM t WHERE service_name='ts-order-service' AND span_name IN ('SELECT ts.orders','Transaction.commit','OrderRepository.findById','OrderRepository.save') GROUP BY ALL ORDER BY span_name, p",
          "claim": "In-process DB-layer spans in ts-order-service jump from roughly 1 ms to 1-2 s p50 in the abnormal period."
        },
        {
          "kind": "metric",
          "sql": "WITH t AS (SELECT 'abn' p, * FROM abnormal_metrics_sum UNION ALL SELECT 'norm', * FROM normal_metrics_sum) SELECT metric, attr_source, attr_destination, p, round(avg(value),2) avg_v FROM t WHERE metric IN ('hubble_tcp_flags_total','hubble_flows_processed_total') AND ((attr_source LIKE '%ts-order-service%' AND attr_destination LIKE '%mysql%') OR (attr_source LIKE '%mysql%' AND attr_destination LIKE '%ts-order-service%')) GROUP BY ALL ORDER BY metric, p",
          "claim": "Order-to-mysql connection shows no drops and no rise in flows, so the network path is not the cause."
        },
        {
          "kind": "metric",
          "sql": "WITH t AS (SELECT 'abn' p, * FROM abnormal_metrics UNION ALL SELECT 'norm', * FROM normal_metrics) SELECT metric, service_name, p, round(avg(value),3) avg_v FROM t WHERE attr_k8s_pod_name LIKE 'ts-order-service%' AND metric IN ('k8s.pod.cpu.usage','k8s.pod.memory.usage','k8s.container.restarts') GROUP BY ALL ORDER BY metric, p",
          "claim": "ts-order-service CPU and memory are flat or lower and it has no restarts, so the pod is not saturated or crashing."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-order-service",
      "to": "ts-seat-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(quantile_cont(p.duration,0.5)/1e6,1) caller_p50_ms, round(quantile_cont(c.duration,0.5)/1e6,1) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name='ts-seat-service' AND c.service_name='ts-order-service' GROUP BY ALL",
          "claim": "Seat service's calls to order-service take about 2.2 s p50 in the abnormal period, matching order's slowdown."
        }
      ]
    },
    {
      "from": "ts-seat-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(quantile_cont(p.duration,0.5)/1e6,1) caller_p50_ms, round(quantile_cont(c.duration,0.5)/1e6,1) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name='ts-travel-service' AND c.service_name='ts-seat-service' GROUP BY ALL",
          "claim": "Travel service's calls to seat-service take about 2.2 s p50 in the abnormal period."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(quantile_cont(p.duration,0.5)/1e6,1) caller_p50_ms, round(quantile_cont(c.duration,0.5)/1e6,1) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name='ts-route-plan-service' AND c.service_name='ts-travel-service' GROUP BY ALL",
          "claim": "Route-plan calls to travel-service take 22 ms p50 callee time while route-plan's own server spans grow to seconds."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(quantile_cont(p.duration,0.5)/1e6,1) caller_p50_ms, round(quantile_cont(c.duration,0.5)/1e6,1) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name='ts-travel-plan-service' AND c.service_name='ts-route-plan-service' GROUP BY ALL",
          "claim": "Travel-plan calls to route-plan take about 4.5 s p50, inherited from the order-service delay."
        }
      ]
    },
    {
      "from": "ts-order-service",
      "to": "ts-security-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(quantile_cont(c.duration,0.5)/1e6,1) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name='ts-security-service' AND c.service_name='ts-order-service' GROUP BY ALL",
          "claim": "Security-service calls to order-service take about 6.3 s p50 in the abnormal period."
        }
      ]
    },
    {
      "from": "ts-security-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(quantile_cont(c.duration,0.5)/1e6,1) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name='ts-preserve-service' AND c.service_name='ts-security-service' GROUP BY ALL",
          "claim": "Preserve-service calls to security-service take about 6.4 s p50 in the abnormal period."
        }
      ]
    },
    {
      "from": "ts-order-service",
      "to": "ts-inside-payment-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(quantile_cont(c.duration,0.5)/1e6,1) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name='ts-inside-payment-service' AND c.service_name='ts-order-service' GROUP BY ALL",
          "claim": "Inside-payment calls to order-service take about 8 s p50 in the abnormal period."
        }
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(quantile_cont(c.duration,0.5)/1e6,1) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name='ts-ui-dashboard' AND c.service_name='ts-preserve-service' GROUP BY ALL",
          "claim": "UI dashboard calls to preserve-service take about 21 s p50 in the abnormal period."
        }
      ]
    },
    {
      "from": "ts-inside-payment-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(quantile_cont(c.duration,0.5)/1e6,1) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name='ts-ui-dashboard' AND c.service_name='ts-inside-payment-service' GROUP BY ALL",
          "claim": "UI dashboard calls to inside-payment-service take about 19 s p50 in the abnormal period."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(quantile_cont(c.duration,0.5)/1e6,1) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name='ts-ui-dashboard' AND c.service_name='ts-travel-plan-service' GROUP BY ALL",
          "claim": "UI dashboard calls to travel-plan-service take about 9.1 s p50 in the abnormal period."
        }
      ]
    },
    {
      "from": "ts-order-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(quantile_cont(c.duration,0.5)/1e6,1) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name='ts-ui-dashboard' AND c.service_name='ts-order-service' GROUP BY ALL",
          "claim": "UI dashboard calls to order-service take about 3.3 s p50 in the abnormal period, directly exposing the user-facing order endpoints."
        }
      ]
    }
  ]
}
